float score = baseScore + objective + safety - risk;
score -= teamFocus * focusPenalty;
return Mathf.Clamp(score, 0f, 100f);

blackboard.ReportIntent(selfId, targetId, objectiveId);
focusCount = blackboard.GetFocusCount(targetId);
allyPressure = blackboard.GetObjectivePressure(slotId);

if (!nav.TryBuildPath(start, goal, out path))
    goal = nav.FindNearbyWalkable(goal);

if (watchdog.IsStalled(self))
    planner.AbandonDestination();

objectiveFloor = mode switch {
    GemGrab => ScoreGemIntent(state),
    BrawlBall => ScoreBallIntent(state),
    Knockout => ScoreSurvivalPressure(state),
};
score = Mathf.Max(score, objectiveFloor);
